def IsBooleanStonePoint (f : B → Bool) : Prop :=
  f ⊥ = false ∧ f ⊤ = true ∧ (∀ a b, f (a ⊓ b) = f a ⊓ f b) ∧
    ∀ a b, f (a ⊔ b) = f a ⊔ f b

